import { createEffect, createSignal, Show, type JSX, type ParentComponent } from "solid-js";

import { ChooserItemSelectedEvent } from "#core/ui/components/fxs-chooser-item.js";
import { Activatable, type ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface ChooserItemProps extends ActivatableProps {
	/** Selected state; when true, shows the selection frame */
	selected?: boolean;
	/** If true, item can be selected even when disabled */
	selectableWhenDisabled?: boolean;
	/** If true, selecting occurs when focused */
	selectOnFocus?: boolean;
	/** If true, selecting occurs when activated */
	selectOnActivate?: boolean;
	/** Shows the selection frame on hover */
	showFrameOnHover?: boolean;
	/** Shows the standard gray bg behind the chooser item */
	showColorBg?: boolean;
	/** Called when the item becomes selected */
	onSelect?: () => void;
	/** Optional icon rendered before content. If string, treated as image URL. */
	icon?: string | JSX.Element;
	/** When using string icon, optionally render locked overlay state */
	iconLocked?: boolean;
	/** Optional classes applied to the inner content container. */
	contentClass?: string;
	/** Optional opacity for the disabled overlay. Defaults to 0.7. */
	disabledOverlayOpacity?: number;
	/** Ref callback to get access to the host element */
	ref?: (el: HTMLDivElement) => void;
}

const ChooserItemComponent: ParentComponent<ChooserItemProps> = (props) => {
	const [isSelected, setIsSelected] = createSignal(false);
	let hostRef: HTMLDivElement | undefined;

	const canSelect = () => (props.selectableWhenDisabled || !(props.disabled || props.disableVisual)) ?? true;

	/**
	 * Dispatches a legacy ChooserItemSelectedEvent for interop with old code.
	 * This allows the solid-based chooser item to work with legacy event listeners.
	 */
	const dispatchLegacySelectedEvent = (): boolean => {
		if (!hostRef) return true;
		return hostRef.dispatchEvent(new ChooserItemSelectedEvent());
	};

	const triggerSelect = () => {
		if (!canSelect()) return;
		if (!isSelected()) {
			setIsSelected(true);
			props.onSelect?.();
		}
	};

	const onFocus = () => {
		props.onFocus?.();
		if (props.selectOnFocus) {
			triggerSelect();
		}
	};

	const onActivate = () => {
		if (props.selectOnActivate) {
			triggerSelect();
			// If no onActivate handler is provided, dispatch the legacy event for interop
			if (!props.onActivate) {
				dispatchLegacySelectedEvent();
				return;
			}
		}
		props.onActivate?.();
	};

	// Keep internal selected state synced with controlled prop
	createEffect(() => setIsSelected(!!props.selected));

	const showFrameOnHover = () => props.showFrameOnHover ?? true;
	const showColorBg = () => props.showColorBg ?? true;
	const disabledOverlayOpacity = () => props.disabledOverlayOpacity ?? 0.7;

	const setRef = (el: HTMLDivElement) => {
		hostRef = el;
		props.ref?.(el);
	};

	return (
		<Activatable
			{...props}
			ref={setRef}
			name={props.name ?? "ChooserItem"}
			onActivate={onActivate}
			onFocus={onFocus}
			class={`fxs-chooser-item flex justify-stretch items-stretch relative ${props.class ?? ""}`}
			classList={{
				"hud_sidepanel_list-bg": showColorBg(),
			}}
		>
			<div class="fxs-chooser-item-highlight absolute inset-0" />

			<div
				class={`fxs-chooser-item-selected img-list-focus-frame absolute inset-0`}
				classList={{
					selected: isSelected(),
					"show-on-hover": showFrameOnHover(),
				}}
			/>

			<div class={`hud_sidepanel_list-bg-no-fill relative flex flex-auto ${props.contentClass ?? ""}`}>
				<Show when={typeof props.icon === "string" ? props.icon : false}>
					{(value) => (
						<div class="relative flex self-center items-center justify-center pointer-events-none size-19">
							<div
								class="fxs-chooser-item-icon-image relative flex flex-col items-center"
								style={{ "background-image": `url(${value()})` }}
							>
								<div class="fxs-chooser-item-lock-bg absolute inset-0" />
								<Show when={props.iconLocked}>
									<div class="fxs-chooser-item-lock-image absolute bg-cover" />
								</Show>
							</div>
							<div class="fxs-chooser-item-icon-bg absolute" />
						</div>
					)}
				</Show>
				<Show when={typeof props.icon !== "string" ? props.icon : false}>{(value) => value()}</Show>

				{props.children}
			</div>

			{/* Disabled overlay */}
			<Show when={props.disabled || props.disableVisual}>
				<div
					class="absolute inset-0 pointer-events-none bg-primary-5"
					style={{ opacity: disabledOverlayOpacity() }}
				/>
			</Show>
		</Activatable>
	);
};

/**
 * ChooserItem - Solid.js implementation of the legacy fxs-chooser-item.
 * Compose this with your own content to build list entries that support selection and activation.
 */
export const ChooserItem = ComponentRegistry.register({
	name: "ChooserItem",
	createInstance: ChooserItemComponent,
	images: ["blp:hud_sidepanel_list-bg", "blp:hud_list-focus_frame"],
});
